import { test, expect } from '@playwright/test';
import * as ui from '../support/ui';

test.setTimeout(240_000);
test.describe("parent plans", () => {
  test("parent plans", { tag: '@functionality' }, async ({ browser }) => {
    const sheet = ui.sheetId();
    const pg_uma = await ui.userPage(browser, "uma", sheet);
    await ui.loadSheet(pg_uma, `${sheet}-c`);
    await ui.setToday(pg_uma, "2026-03-01");
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "10.00"})).toBe(true);
    const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A"}));
    await ui.loadSheet(pg_uma, sheet);
    await ui.setToday(pg_uma, "2026-03-01");
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "20.00"})).toBe(true);
    const p_ada_2 = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A"}));
    const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "B"}));
    await ui.loadSheet(pg_uma, `${sheet}-c`);
    await ui.setSetting(pg_uma, "parent", `${sheet}`);
    await ui.loadSheet(pg_uma, sheet);
    const pl_ada_1 = ui.must(await ui.addPlan(pg_uma, p_ada_2, {"amount": "10.00", "start": "2026-03-01", "end": "2026-03-20", "sheet": `${sheet}-c`, "every": "5"}));
    const pl_ben_2 = ui.must(await ui.addPlan(pg_uma, p_ben, {"amount": "5.00", "start": "2026-03-01", "end": "2026-03-20", "sheet": `${sheet}-c`, "every": "5"}));
    expect(await ui.addPlan(pg_uma, p_ada_2, {"amount": "1.00", "start": "2026-03-01", "end": "2026-03-20", "sheet": `${sheet}-x`, "every": "5"})).toBeNull();
    expect(await ui.generatePlans(pg_uma)).toBe(1);
    await ui.setToday(pg_uma, "2026-03-12");
    expect(await ui.generatePlans(pg_uma)).toBe(2);
    await ui.refresh(pg_uma);
    await expect(pg_uma.getByTestId("person-row-" + p_ada_2).getByTestId("person-claimed")).toHaveText("0.00");
    await expect(pg_uma.getByTestId("person-row-" + p_ben).getByTestId("person-claimed")).toHaveText("0.00");
    await expect(pg_uma.getByTestId("plan-row-" + pl_ada_1).getByTestId("plan-generated")).toHaveText("3");
    await expect(pg_uma.getByTestId("plan-row-" + pl_ada_1).getByTestId("plan-next-dates")).toHaveText("2026-03-16");
    await expect(pg_uma.getByTestId("plan-row-" + pl_ada_1).getByTestId("plan-paused")).toHaveText("no");
    await expect(pg_uma.getByTestId("plan-row-" + pl_ada_1).getByTestId("plan-change-line")).toHaveText([]);
    await expect(pg_uma.getByTestId("plan-row-" + pl_ben_2).getByTestId("plan-generated")).toHaveText("0");
    await expect(pg_uma.getByTestId("plan-row-" + pl_ben_2).getByTestId("plan-next-dates")).toHaveText("2026-03-16");
    await expect(pg_uma.getByTestId("plan-row-" + pl_ben_2).getByTestId("plan-paused")).toHaveText("no");
    await expect(pg_uma.getByTestId("plan-row-" + pl_ben_2).getByTestId("plan-change-line")).toHaveText([]);
    await ui.expectAudit(sheet, [
      `RATE_SET sheet=${sheet} by=uma grade=A rate=20.00`,
      `PERSON_ADDED sheet=${sheet} by=uma name=Ada grade=A`,
      `ROLLUP sheet=${sheet} by=uma person=Ada claimed=0.00 due-total=0.00 overdue-total=0.00`,
      `PERSON_ADDED sheet=${sheet} by=uma name=Ben grade=B`,
      `ROLLUP sheet=${sheet} by=uma person=Ben claimed=0.00 due-total=n/a overdue-total=0.00`,
      `PLAN_ADDED sheet=${sheet} by=uma name=Ada amount=10.00 start=2026-03-01 every=5 end=2026-03-20 sheet=${sheet}-c`,
      `PLAN_ADDED sheet=${sheet} by=uma name=Ben amount=5.00 start=2026-03-01 every=5 end=2026-03-20 sheet=${sheet}-c`,
      `SNAPSHOT sheet=${sheet} by=uma name=Ada due-total=0.00`,
      `SNAPSHOT sheet=${sheet} by=uma name=Ben due-total=n/a`
    ]);
    await ui.loadSheet(pg_uma, `${sheet}-c`);
    const c_ada_0 = await ui.claimAt(pg_uma, p_ada, 0);
    const c_ada_1 = await ui.claimAt(pg_uma, p_ada, 1);
    const c_ada_2 = await ui.claimAt(pg_uma, p_ada, 2);
    await ui.refresh(pg_uma);
    await expect(pg_uma.getByTestId("person-row-" + p_ada).getByTestId("person-claimed")).toHaveText("0.00");
    await expect(pg_uma.getByTestId("claim-row-" + c_ada_2).getByTestId("claim-amount")).toHaveText("10.00");
    await expect(pg_uma.getByTestId("claim-row-" + c_ada_2).getByTestId("claim-date")).toHaveText("2026-03-11");
    await expect(pg_uma.getByTestId("claim-row-" + c_ada_2).getByTestId("claim-status")).toHaveText("DRAFT");
    await expect(pg_uma.getByTestId("claim-row-" + c_ada_1).getByTestId("claim-amount")).toHaveText("10.00");
    await expect(pg_uma.getByTestId("claim-row-" + c_ada_1).getByTestId("claim-date")).toHaveText("2026-03-06");
    await expect(pg_uma.getByTestId("claim-row-" + c_ada_1).getByTestId("claim-status")).toHaveText("DRAFT");
    await expect(pg_uma.getByTestId("claim-row-" + c_ada_0).getByTestId("claim-amount")).toHaveText("10.00");
    await expect(pg_uma.getByTestId("claim-row-" + c_ada_0).getByTestId("claim-date")).toHaveText("2026-03-01");
    await expect(pg_uma.getByTestId("claim-row-" + c_ada_0).getByTestId("claim-status")).toHaveText("DRAFT");
    await ui.expectAudit(`${sheet}-c`, [
      `RATE_SET sheet=${sheet}-c by=uma grade=A rate=10.00`,
      `PERSON_ADDED sheet=${sheet}-c by=uma name=Ada grade=A`,
      `ROLLUP sheet=${sheet}-c by=uma person=Ada claimed=0.00 due-total=0.00 overdue-total=0.00`,
      `SETTING_CHANGED sheet=${sheet}-c by=uma key=parent value=${sheet}`,
      `CLAIM_ADDED sheet=${sheet}-c by=uma person=Ada amount=10.00 date=2026-03-01`,
      `CLAIM_ADDED sheet=${sheet}-c by=uma person=Ada amount=10.00 date=2026-03-06`,
      `CLAIM_ADDED sheet=${sheet}-c by=uma person=Ada amount=10.00 date=2026-03-11`
    ]);
  });
  test("parent plans scenario 1", { tag: '@functionality' }, async ({ browser }) => {
    const sheet = ui.sheetId();
    const pg_uma = await ui.userPage(browser, "uma", sheet);
    await ui.setToday(pg_uma, "2026-04-05");
    await ui.setSetting(pg_uma, "floor", "2.00");
    await ui.setSetting(pg_uma, "terms", "30");
    await ui.setSetting(pg_uma, "period-numbering-from", "2026-03-01");
    await ui.setSetting(pg_uma, "terms-A", "3");
    await ui.setSetting(pg_uma, "cap", "5.00");
    expect(await ui.addHoliday(pg_uma, "2026-03-13")).toBe(true);
    await ui.setSetting(pg_uma, "alert-threshold", "3.00");
    expect(await ui.setSettingDated(pg_uma, "rounding", "half-up", "2026-03-01", "half-up")).toBe(true);
    await ui.setSetting(pg_uma, "review-threshold", "4.00");
    await ui.setSetting(pg_uma, "escalate-after", "7");
    await ui.setSetting(pg_uma, "proof-kinds", "receipt");
    await ui.setSetting(pg_uma, "score-mid", "0");
    await ui.setSetting(pg_uma, "score-high", "1");
    await ui.setSetting(pg_uma, "score-log", "on");
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "10.00"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "7.50"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "20.00", "from": "2026-03-16"})).toBe(true);
    expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
    const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "B", "terms": "20"}));
    const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "C"}));
    const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "B", "contact": " Ada@x "}));
    const pl_cam_1 = ui.must(await ui.addPlan(pg_uma, p_cam, {"amount": "3.33", "start": "2026-02-20", "end": "2026-04-30", "day": "1"}));
    expect(await ui.hold(pg_uma, p_ada, {"from": "2026-03-09", "to": "2026-03-20"})).toBe(true);
    expect(await ui.setSettingDated(pg_uma, "late-pct", "10.00", "2026-03-15", "10.00")).toBe(true);
    expect(await ui.activity(pg_uma)).toEqual(["uma HOLIDAY_ADDED 1", "uma PERIOD_ADDED 1", "uma PERSON_ADDED 3", "uma PERSON_HELD 1", "uma PLAN_ADDED 1", "uma RATE_SET 3", "uma ROLLUP 3", "uma SETTING_CHANGED 14"]);
    expect(await ui.addPatron(pg_uma, p_ada, "Ben")).toBe(true);
    expect(await ui.periodAction(pg_uma, "P1", "close")).toBe(true);
    expect(await ui.editPerson(pg_uma, p_cam, {"terms": ""})).toBe(true);
    expect(await ui.generatePlans(pg_uma)).toBe(2);
    const c_cam_0 = await ui.claimAt(pg_uma, p_cam, 0);
    const c_cam_1 = await ui.claimAt(pg_uma, p_cam, 1);
    await ui.refresh(pg_uma);
    await expect(pg_uma.getByTestId("person-row-" + p_cam).getByTestId("person-claimed")).toHaveText("0.00");
    await expect(pg_uma.getByTestId("person-row-" + p_cam).getByTestId("person-due-total")).toHaveText("0.00");
    await expect(pg_uma.getByTestId("claim-row-" + c_cam_1).getByTestId("claim-due")).toHaveText("1.00");
    await expect(pg_uma.getByTestId("claim-row-" + c_cam_1).getByTestId("claim-status")).toHaveText("DRAFT");
    await expect(pg_uma.getByTestId("claim-row-" + c_cam_1).getByTestId("claim-stated")).toHaveText("no");
    await expect(pg_uma.getByTestId("claim-row-" + c_cam_0).getByTestId("claim-due")).toHaveText("1.00");
